package vn.teasmart.backend.service;
import java.time.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;
import org.springframework.security.oauth2.jwt.Jwt;
import vn.teasmart.backend.config.GoogleAuthConfig;
import vn.teasmart.backend.security.GoogleTokenVerifier;
import vn.teasmart.backend.exception.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class GoogleLinkFlowTest {
 final AtomicReference<Instant> now=new AtomicReference<>(Instant.parse("2026-11-06T00:00:00Z"));
 final Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now.get();}};
 final GoogleCodeClient client=mock(GoogleCodeClient.class);final GoogleTokenVerifier verifier=mock(GoogleTokenVerifier.class);final GoogleLinkService links=mock(GoogleLinkService.class);GoogleLinkFlow flow;
 Jwt jwt(String token,long owner,Instant issued){return Jwt.withTokenValue(token).header("alg","HS256").subject(Long.toString(owner)).issuedAt(issued).expiresAt(now.get().plusSeconds(3600)).build();}
 @BeforeEach void setup(){flow=new GoogleLinkFlow(new GoogleAuthConfig(true,"fixture","http://localhost:3115"),client,verifier,links,clock);when(links.status(42L)).thenReturn(new GoogleLinkService.LinkStatus(false,true,null));when(client.authorization(anyString(),anyString(),anyString())).thenAnswer(i->i.getArgument(0)+"|"+i.getArgument(1)+"|"+i.getArgument(2));}
 String[] parts(GoogleLinkFlow.Launch l){return l.response().authorizationUrl().split("\\|");}
 @Test void pkceNonceAndSameSessionAreRequiredBeforeDatabaseWrite(){var jwt=jwt("session",42,now.get());var l=flow.start(jwt,"http://localhost:3115",null);var p=parts(l);when(client.exchange(eq("code"),anyString())).thenAnswer(i->{assertEquals(p[2],GoogleLinkFlow.hash(i.getArgument(1)));return "token";});var identity=new GoogleTokenVerifier.Identity("sub","other@example.invalid","Name");when(verifier.verify("token",p[1])).thenReturn(identity);assertEquals("http://localhost:3115/account?google_link=ready",flow.callback(l.binding(),p[0],"code",null));verify(links,never()).attachVerified(anyLong(),any());assertThrows(GoogleAuthException.class,()->flow.complete(jwt("other-session",42,now.get()),l.binding(),"http://localhost:3115"));assertThrows(GoogleAuthException.class,()->flow.complete(jwt("session",43,now.get()),l.binding(),"http://localhost:3115"));flow.complete(jwt,l.binding(),"http://localhost:3115");verify(links).attachVerified(42L,identity);assertThrows(GoogleAuthException.class,()->flow.complete(jwt,l.binding(),"http://localhost:3115"));}
 @Test void wrongStateLoginCookieAndExpiryNeverExchange(){var l=flow.start(jwt("session",42,now.get()),"http://localhost:3115",null);assertThrows(GoogleAuthException.class,()->flow.callback("LOGIN_COOKIE",parts(l)[0],"code",null));assertThrows(GoogleAuthException.class,()->flow.callback(l.binding(),"wrong","code",null));now.set(now.get().plusSeconds(301));assertThrows(GoogleAuthException.class,()->flow.callback(l.binding(),parts(l)[0],"code",null));verify(client,never()).exchange(anyString(),anyString());}
 @Test void cancellationCannotCompleteOrReplay(){var jwt=jwt("session",42,now.get());var l=flow.start(jwt,"http://localhost:3115",null);assertEquals("http://localhost:3115/account?google_link=cancelled",flow.callback(l.binding(),parts(l)[0],null,"access_denied"));assertThrows(GoogleAuthException.class,()->flow.callback(l.binding(),parts(l)[0],"code",null));assertThrows(GoogleAuthException.class,()->flow.complete(jwt,l.binding(),"http://localhost:3115"));verify(links,never()).attachVerified(anyLong(),any());}
 @Test void staleSessionAndForeignOriginRejected(){assertThrows(ProfileException.class,()->flow.start(jwt("old",42,now.get().minusSeconds(601)),"http://localhost:3115",null));assertThrows(GoogleAuthException.class,()->flow.start(jwt("session",42,now.get()),"https://attacker.invalid",null));}
 @Test void invalidIdentityNeverLinks(){var jwt=jwt("session",42,now.get());var l=flow.start(jwt,"http://localhost:3115",null);when(client.exchange(anyString(),anyString())).thenReturn("invalid");when(verifier.verify(anyString(),anyString())).thenThrow(GoogleAuthException.failed());assertThrows(GoogleAuthException.class,()->flow.callback(l.binding(),parts(l)[0],"code",null));assertThrows(GoogleAuthException.class,()->flow.complete(jwt,l.binding(),"http://localhost:3115"));verify(links,never()).attachVerified(anyLong(),any());}
 @Test void actualAuthorizationUrlContainsCodePkceNonceAndNeverClientSecret(){var c=new GoogleCodeClient(new GoogleAuthConfig(true,"fixture-client","http://localhost:3001"),"fixture-secret","http://localhost:3001/api/auth/google/link/callback");var url=c.authorization("state-fixture","nonce-fixture","challenge-fixture");assertTrue(url.startsWith("https://accounts.google.com/o/oauth2/v2/auth?"));for(String value:java.util.List.of("response_type=code","code_challenge_method=S256","code_challenge=challenge-fixture","nonce=nonce-fixture","state=state-fixture","prompt=select_account"))assertTrue(url.contains(value));assertFalse(url.contains("fixture-secret"));}
 @Test void missingSecretAndUntrustedRedirectFailClosed(){var config=new GoogleAuthConfig(true,"fixture","http://localhost:3001");assertThrows(GoogleAuthException.class,()->new GoogleCodeClient(config,"","http://localhost:3001/api/auth/google/link/callback").available());assertThrows(IllegalArgumentException.class,()->new GoogleCodeClient(config,"fixture","http://evil.invalid/api/auth/google/link/callback"));}
}